var lager = new Dictionary<string, int>
{
    ["Äpfel"] = 10,
    ["Birnen"] = 4
};
lager["Äpfel"] = 12;          // überschreibt 10
lager["Äpfel"] += 3;          // jetzt 15
// lager.Add("Birnen", 7);    // ArgumentException: Schlüssel gibt es schon!
Console.WriteLine(lager["Äpfel"]);
// Ausgabe: 15

var hauptstadt = new Dictionary<string, string>
{
    ["Österreich"] = "Wien",
    ["Italien"] = "Rom"
};

if (hauptstadt.TryGetValue("Italien", out string stadt))
{
    Console.WriteLine(stadt);
}
if (!hauptstadt.ContainsKey("Spanien"))
{
    Console.WriteLine("Spanien unbekannt");
}
// Ausgabe:
// Rom
// Spanien unbekannt

string[] woerter = { "ja", "nein", "ja", "vielleicht", "ja" };
var anzahl = new Dictionary<string, int>();

foreach (string w in woerter)
{
    if (anzahl.ContainsKey(w))
        anzahl[w]++;
    else
        anzahl[w] = 1;
}

foreach (var paar in anzahl)
{
    Console.WriteLine($"{paar.Key}: {paar.Value}");
}
// Ausgabe:
// ja: 3
// nein: 1
// vielleicht: 1

